const string W="D:/project/MTGB/design-demos/battlefield-redesign-2026-10-24/";
if(!Application.isPlaying||UnityEngine.SceneManagement.SceneManager.GetActiveScene().name!=ForgeBattlefieldController.SceneName)throw new System.Exception("Integrated play scene required");
var ui=UnityEngine.Object.FindFirstObjectByType<ForgeBattlefieldController>()??new GameObject("SupportSizeValidation").AddComponent<ForgeBattlefieldController>();
var flags=System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance;
var results=new System.Collections.Generic.List<object>();int assertions=0;
void Check(bool ok,string message){assertions++;if(!ok)throw new System.Exception(message);}
Rect Bounds(RectTransform r){var cs=new Vector3[4];r.GetWorldCorners(cs);return Rect.MinMaxRect(cs.Min(p=>p.x),cs.Min(p=>p.y),cs.Max(p=>p.x),cs.Max(p=>p.y));}
ForgeSeatView Sample(string mode){var v=JsonUtility.FromJson<ForgeSeatView>(System.IO.File.ReadAllText(W+"native-full-seat.json"));foreach(var p in v.players){var fixedCards=p.battlefield.Where(c=>c.land||c.creature);var supports=p.battlefield.Where(c=>!c.land&&!c.creature&&!c.planeswalker&&!c.battle).ToArray();var walkers=p.battlefield.Where(c=>!c.land&&!c.creature&&c.planeswalker&&!c.battle).ToArray();var battles=p.battlefield.Where(c=>!c.land&&!c.creature&&c.battle).ToArray();var extra=mode.StartsWith("one-artifact",System.StringComparison.Ordinal)?supports.Take(1):mode=="three-support"?supports:mode=="one-each"?supports.Take(1).Concat(walkers).Concat(battles):supports.Concat(walkers).Concat(battles);if(mode=="crowded")extra=Enumerable.Range(0,4).SelectMany(n=>supports.Concat(walkers).Concat(battles).Select(c=>{var copy=JsonUtility.FromJson<ForgeCardView>(JsonUtility.ToJson(c));copy.id+=n*1000;return copy;}));p.battlefield=fixedCards.Concat(extra).ToArray();}v.boardKey="support-size-"+mode;return v;}
System.Collections.IEnumerator Run(){string lang=GamePreferences.Language;float scale=GamePreferences.TextScale;var input=UnityEngine.EventSystems.EventSystem.current.currentInputModule;bool inputEnabled=input.enabled;input.enabled=false;ui.enabled=false;
 try{GamePreferences.SetLanguage("zh-CN");GamePreferences.SetScale(1);while(!GamePreferences.Ready)yield return null;
 foreach(string mode in new[]{"one-artifact","three-support","one-each","one-artifact-restored","full","crowded","many-lands","many-markers"}){
  var v=Sample(mode);
  if(mode=="many-lands")foreach(var p in v.players){var baseLands=p.battlefield.Where(c=>c.land&&!c.creature).ToArray();p.battlefield=p.battlefield.Where(c=>!c.land||c.creature).Concat(Enumerable.Range(0,4).SelectMany(n=>baseLands.Select(c=>{var copy=JsonUtility.FromJson<ForgeCardView>(JsonUtility.ToJson(c));copy.id+=5000*n;return copy;}))).ToArray();}
  if(mode=="many-markers")foreach(var p in v.players){var original=p.effectMarkers;p.effectMarkers=Enumerable.Range(0,3).SelectMany(n=>original.Select(c=>{var copy=JsonUtility.FromJson<ForgeCardView>(JsonUtility.ToJson(c));copy.id+=10000*n;return copy;})).ToArray();}
  ui.Present(v,1,false,_=>{},null,"");yield return new WaitForSecondsRealtime(.45f);yield return new WaitForEndOfFrame();Canvas.ForceUpdateCanvases();
  var arena=(System.Collections.IDictionary)typeof(ForgeBattlefieldController).GetField("arenaCards",flags).GetValue(ui);var lanes=(System.Collections.Generic.Dictionary<string,UnityEngine.UI.ScrollRect>)typeof(ForgeBattlefieldController).GetField("denseFieldRows",flags).GetValue(ui);
  var widths=new System.Collections.Generic.List<float>();float creature=0;
  foreach(System.Collections.DictionaryEntry entry in arena){var item=entry.Value;var r=(RectTransform)item.GetType().GetField("root").GetValue(item);if(!r.gameObject.activeInHierarchy)continue;string key=entry.Key.ToString();if(key.StartsWith("YourCreatures:"))creature=Mathf.Max(creature,r.rect.width);if(key.StartsWith("YourSupport:")||key.StartsWith("OpponentSupport:"))widths.Add(r.rect.width);}
  Check(widths.Count>0&&creature>0,"Missing rendered support/creature in "+mode);Check(widths.Min()/creature>=.70f,"Support width below readable ratio in "+mode+": "+widths.Min()+"/"+creature);
  if(mode.StartsWith("one-artifact",System.StringComparison.Ordinal))Check(widths.Min()/creature>.95f,"A single support card did not recover its full width");
  var authored=(Transform)typeof(ForgeBattlefieldController).GetField("authored",flags).GetValue(ui);
  foreach(bool own in new[]{true,false}){string prefix=own?"Your":"Opponent";var info=new System.Collections.Generic.List<Rect>{Bounds((RectTransform)authored.Find(own?"PlayerPlate":"OpponentPlate"))};var plate=authored.Find(own?"PlayerPlate":"OpponentPlate");var ctr=plate.Find("PlayerCounters")as RectTransform;if(ctr!=null)info.Add(Bounds(ctr));foreach(var b in plate.GetComponentsInChildren<UnityEngine.UI.Button>())if(b.gameObject.activeInHierarchy)info.Add(Bounds((RectTransform)b.transform));foreach(System.Collections.DictionaryEntry entry in arena){if(!entry.Key.ToString().StartsWith(prefix+"Emblem:",System.StringComparison.Ordinal))continue;var item=entry.Value;var r=(RectTransform)item.GetType().GetField("root").GetValue(item);if(r.gameObject.activeInHierarchy)info.Add(Bounds(r));}foreach(System.Collections.DictionaryEntry entry in arena){if(!entry.Key.ToString().StartsWith(prefix+"Lands:",System.StringComparison.Ordinal))continue;var item=entry.Value;var r=(RectTransform)item.GetType().GetField("root").GetValue(item);if(!r.gameObject.activeInHierarchy)continue;foreach(var rect in info)Check(!Bounds(r).Overlaps(rect),"Land overlaps left information in "+mode+" "+entry.Key);}}
  var laneStates=new System.Collections.Generic.List<object>();
  foreach(bool own in new[]{true,false}){string prefix=own?"Your":"Opponent";var active=new System.Collections.Generic.List<RectTransform>();foreach(string kind in new[]{"Support","Planeswalkers","Battles"}){if(!lanes.TryGetValue(prefix+kind,out var lane)||!lane.gameObject.activeSelf)continue;var r=(RectTransform)lane.transform;Check(own?r.anchoredPosition.y+r.rect.height*.5f<=0:r.anchoredPosition.y-r.rect.height*.5f>=0,"Support crossed midline in "+mode+" "+kind);foreach(var prior in active)Check(Mathf.Abs(r.anchoredPosition.y-prior.anchoredPosition.y)>=(r.rect.height+prior.rect.height)*.5f-1,"Support categories overlap in "+mode);active.Add(r);laneStates.Add(new{side=prefix,kind,width=r.rect.width,height=r.rect.height,y=r.anchoredPosition.y,contentWidth=lane.content.rect.width});if(mode=="crowded"){Check(lane.content.rect.width>r.rect.width,"Crowded lane lost horizontal overflow "+kind);}}}
  results.Add(new{mode,minimumSupportWidth=widths.Min(),creatureWidth=creature,ratio=widths.Min()/creature,lanes=laneStates});
  if(mode=="full"){ScreenCapture.CaptureScreenshot(W+"support-size-after.png");yield return new WaitForEndOfFrame();}
 }
 var serializer=System.AppDomain.CurrentDomain.GetAssemblies().First(a=>a.GetName().Name=="Newtonsoft.Json").GetType("Newtonsoft.Json.JsonConvert").GetMethod("SerializeObject",new[]{typeof(object)});System.IO.File.WriteAllText(W+"support-size-validation.json",(string)serializer.Invoke(null,new object[]{new{status="PASS",assertions,scope="Actual Unity layout projection; no rules or network outcomes",results}}));
 }finally{input.enabled=inputEnabled;GamePreferences.SetLanguage(lang);GamePreferences.SetScale(scale);}
}
UnityEngine.Object.FindFirstObjectByType<GamePreferences>().StartCoroutine(Run());return "Validating support sizes on five actual Unity projections";
